/* Configurable hall directory and per-hall daily operating programs. */
const newProgram=(name='Evening',start='18:00',end='23:00',buffer=60)=>({name,start,end,buffer});
const newHall=(name='',capacity=150,price=150000)=>({id:'H-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name,capacity,price,programs:[newProgram()]});
const defaultHallConfig=()=>[['Silver Marquee Hall',300,250000],['Emerald Banquet',150,150000]].map(([name,capacity,price],i)=>({id:'demo-'+i,name,capacity,price,programs:[newProgram('Morning','09:00','12:00'),newProgram('Afternoon','13:00','16:00'),newProgram()]}));
function configuredHalls(){if(!Array.isArray(installState.config.hallConfig)||!installState.config.hallConfig.length){const old=installState.config.venue1;let list=installState.status==='fresh'?[newHall('Silver Marquee Hall',300,250000)]:defaultHallConfig();if(old?.v0){list=[newHall(old.v0,old.v1||300,installState.config.venue3?.v0||250000)];if(old.v2)list.push(newHall(old.v2,old.v3||150,installState.config.venue3?.v1||150000));if(installState.config.venue2?.v0)list.forEach(h=>h.programs=[newProgram('Morning',installState.config.venue2.v0,'12:00'),newProgram('Afternoon',installState.config.venue2.v1||'13:00','16:00'),newProgram('Evening',installState.config.venue2.v2||'18:00','23:00',installState.config.venue2.v3||60)])}installState.config.hallConfig=list;persistInstall()}return installState.config.hallConfig}
const isConfigWizard=()=>mode==='install'&&page==='start'&&installState.stage===5&&[1,2,3].includes(setupStep);
let managementDraft=null;
const editingHalls=()=>isConfigWizard()?configuredHalls():(managementDraft||(managementDraft=JSON.parse(JSON.stringify(configuredHalls()))));
const countLabel=(n,word)=>`${n} ${word}${n===1?'':'s'}`;
function cfgInput(label,name,value,type='text',extra=''){return `<label class="field">${esc(label)}<input type="${type}" name="${esc(name)}" value="${esc(value)}" ${extra} required></label>`}
function cfgButton(label,a,style='outline',icon=''){return `<button type="button" class="btn ${style}" data-action="${a}">${icon?ic(icon):''}${esc(label)}</button>`}
function hallEditor(list){return `<div class="config-intro"><div><h3>How many halls do you operate?</h3><p>Start with one hall and add as many as you need. Each hall is managed separately.</p></div><span class="config-count">${countLabel(list.length,'hall')}</span></div><div class="config-stack">${list.map((h,i)=>`<section class="config-card"><div class="config-card-head"><div class="config-index">${i+1}</div><div><h3>Hall ${i+1}</h3><small>Venue name and maximum guest capacity</small></div>${list.length>1?cfgButton('Remove','cfg-remove-hall:'+i,'danger sm'):''}</div><div class="fields">${cfgInput('Hall name','cfg-h-'+i+'-name',h.name,'text','placeholder="e.g. Grand Marquee"')}${cfgInput('Guest capacity','cfg-h-'+i+'-capacity',h.capacity,'number','min="1" step="1"')}</div></section>`).join('')}</div><button type="button" class="config-add" data-action="cfg-add-hall">${ic('plus')} Add another hall</button><p class="muted config-help">One hall is enough to continue. You can add more halls later from Manage your business.</p>`}
function programEditor(list){return `<div class="config-intro"><div><h3>Set up your daily programs</h3><p>Choose one, two, three or more programs per hall. Enter the names and times that suit your business.</p></div><span class="config-count">${countLabel(list.reduce((s,h)=>s+h.programs.length,0),'program')}</span></div><div class="config-stack">${list.map((h,i)=>`<section class="config-card"><div class="config-card-head"><div class="config-index">${i+1}</div><div><h3>${esc(h.name||'Hall '+(i+1))}</h3><small>${countLabel(h.programs.length,'daily program')} · Capacity ${esc(h.capacity)}</small></div>${i>0?cfgButton('Copy first hall schedule','cfg-copy:'+i,'outline sm'):''}</div>${h.programs.map((p,j)=>`<div class="program-editor"><div class="program-head"><b>Program ${j+1}</b>${h.programs.length>1?cfgButton('Remove','cfg-remove-program:'+i+':'+j,'danger sm'):''}</div><div class="program-fields">${cfgInput('Program name','cfg-p-'+i+'-'+j+'-name',p.name,'text','placeholder="e.g. Evening"')}${cfgInput('Start time','cfg-p-'+i+'-'+j+'-start',p.start,'time')}${cfgInput('End time','cfg-p-'+i+'-'+j+'-end',p.end,'time')}${cfgInput('Cleanup buffer (min)','cfg-p-'+i+'-'+j+'-buffer',p.buffer,'number','min="0" max="1439" step="1"')}</div></div>`).join('')}<button type="button" class="config-add compact" data-action="cfg-add-program:${i}">${ic('plus')} Add another program</button></section>`).join('')}</div><p class="muted config-help">An end time before the start time means the program ends the following day. Programs and cleanup periods cannot overlap.</p>`}
function priceEditor(list){return `<div class="config-intro"><div><h3>Package prices by hall</h3><p>Set the initial price for each hall. Add more pricing tiers later from Packages & pricing.</p></div></div><div class="config-stack">${list.map((h,i)=>`<section class="config-card"><div class="config-card-head"><div class="config-index">${i+1}</div><div><h3>${esc(h.name)}</h3><small>1–${esc(h.capacity)} guests</small></div></div>${cfgInput('Base package price (PKR)','cfg-h-'+i+'-price',h.price,'number','min="1" step="1"')}</section>`).join('')}</div>`}
function hallValidation(list){if(!list.length)return 'Add at least one hall.';let names=new Set;for(let h of list){let n=h.name.trim().toLowerCase();if(!n||!Number.isInteger(+h.capacity)||+h.capacity<1)return 'Enter a name and positive whole-number capacity for every hall.';if(names.has(n))return 'Hall names must be unique.';names.add(n)}return ''}
const minutes=t=>/^\d\d:\d\d$/.test(t)?Number(t.slice(0,2))*60+Number(t.slice(3)):NaN;
function programValidation(list){for(let h of list){if(!h.programs.length)return `Add at least one daily program for ${h.name}.`;let names=new Set,intervals=[];for(let p of h.programs){let n=p.name.trim().toLowerCase(),s=minutes(p.start),e=minutes(p.end),b=+p.buffer;if(!n||names.has(n))return `Use unique, non-empty program names in ${h.name}.`;names.add(n);if(!Number.isFinite(s)||!Number.isFinite(e)||s<0||s>=1440||e<0||e>=1440||s===e||!Number.isInteger(b)||b<0||b>=1440)return `Check the start, end and cleanup time for ${h.name} · ${p.name}.`;if(e<s)e+=1440;e+=b;if(e-s>1440)return `The program and cleanup time cannot exceed a full day in ${h.name}.`;intervals.push([s,e,p.name])}for(let i=0;i<intervals.length;i++)for(let j=i+1;j<intervals.length;j++)for(let shift of [-1440,0,1440]){let [a,b]=intervals[i],[c,d]=intervals[j];if(a<d+shift&&c+shift<b)return `Programs or cleanup periods overlap in ${h.name}: ${intervals[i][2]} and ${intervals[j][2]}.`}}return ''}
function priceValidation(list){return list.some(h=>!Number.isFinite(+h.price)||+h.price<=0)?'Enter a positive package price for each hall.':''}
const oldFormFields=formFields;
formFields=function(fs){if(isConfigWizard()){let list=configuredHalls();return setupStep===1?hallEditor(list):setupStep===2?programEditor(list):priceEditor(list)}return oldFormFields(fs)};
const oldAdvanceVenue=advanceVenue;
advanceVenue=function(fd){if([1,2,3].includes(setupStep)){let list=configuredHalls(),err=setupStep===1?hallValidation(list):setupStep===2?programValidation(list):priceValidation(list);if(err)return installFail(err);persistInstall()}if(setupStep===9){let list=configuredHalls(),err=hallValidation(list)||programValidation(list)||priceValidation(list);if(err)return installFail(err)}oldAdvanceVenue(fd)};
const oldInstallWizard=installWizard;
installWizard=function(){let html=oldInstallWizard();if(installState.stage===5&&setupStep===9){let list=configuredHalls();html=html.replace('<div class="note">License verification',`<div class="config-review"><h3>Your halls and programs</h3>${list.map(h=>`<div class="check-row"><div><b>${esc(h.name)}</b><small>${esc(h.capacity)} guests · ${esc(money(h.price))}</small><small>${h.programs.map(p=>`${esc(p.name)}: ${esc(p.start)}–${esc(p.end)}`).join(' · ')}</small></div>${badge(countLabel(h.programs.length,'program'))}</div>`).join('')}</div><div class="note">License verification`)}return html};
function synchronizeHallNames(){if(installState.status!=='installed')return;let list=configuredHalls();halls.splice(0,halls.length,...list.map(h=>h.name));if(!halls.includes(booking.hall))booking.hall=halls[0];const current=list.find(h=>h.name===booking.hall);if(current&&!current.programs.some(p=>p.name===booking.program))booking.program=current.programs[0].name}
const beforeRead=readRoute;
readRoute=function(){managementDraft=null;synchronizeHallNames();beforeRead()};
const oldGeneric=generic;
generic=function(c,key){if(key==='venue-programs'||key==='venue-pricing'){let list=editingHalls();return pagehead(key==='venue-programs'?'Halls & daily programs':'Packages & pricing',key==='venue-programs'?'Manage hall capacity and the daily operating times without reopening installation.':'Set prices for all configured halls.')+`<form id="manage-halls-form">${key==='venue-programs'?card('Your halls',hallEditor(list))+card('Daily programs by hall',programEditor(list)):card('Price per hall',priceEditor(list))}<div class="actions">${cfgButton('Discard changes','cfg-discard','outline')}<button class="btn gold" type="submit">Save changes</button></div><p class="muted config-help">Prototype only. Production must preserve bookings and historical pricing, and prevent deletion of halls or programs with protected records.</p></form>`}return oldGeneric(c,key)};
ownerGroups.find(g=>g[0]==='Manage your business')[1].find(r=>r[0]==='programs')[1]='Halls & programs';
const cfgOldAction=action;
action=function(s){let [a,raw,jraw]=s.split(':'),i=+raw,j=+jraw;if(!a.startsWith('cfg-'))return cfgOldAction(s);let list=editingHalls();if(a==='cfg-add-hall')list.push(newHall());else if(a==='cfg-remove-hall'&&list.length>1)list.splice(i,1);else if(a==='cfg-add-program'){let h=list[i];if(h){let p=h.programs.at(-1),start=(minutes(p.end)+(+p.buffer||0))%1440,end=(start+120)%1440,fmt=m=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');h.programs.push(newProgram('Program '+(h.programs.length+1),fmt(start),fmt(end),60))}}else if(a==='cfg-remove-program'&&list[i]?.programs.length>1)list[i].programs.splice(j,1);else if(a==='cfg-copy'&&list[i])list[i].programs=JSON.parse(JSON.stringify(list[0].programs));else if(a==='cfg-discard')managementDraft=null;installError='';if(isConfigWizard())persistInstall();render()};
document.addEventListener('input',e=>{let n=e.target.name||'',m=n.match(/^cfg-h-(\d+)-(name|capacity|price)$/),p=n.match(/^cfg-p-(\d+)-(\d+)-(name|start|end|buffer)$/);if(!m&&!p)return;let list=editingHalls();if(m&&list[+m[1]])list[+m[1]][m[2]]=e.target.value;if(p&&list[+p[1]]?.programs[+p[2]])list[+p[1]].programs[+p[2]][p[3]]=e.target.value;if(isConfigWizard())persistInstall()},true);
document.addEventListener('submit',e=>{if(e.target.id!=='manage-halls-form')return;e.preventDefault();e.stopImmediatePropagation();let list=editingHalls(),err=hallValidation(list)||programValidation(list)||priceValidation(list);if(err){toast(err);return}installState.config.hallConfig=JSON.parse(JSON.stringify(list));persistInstall();managementDraft=null;synchronizeHallNames();render();toast('Hall and program configuration saved in the mock.')},true);
/* Use saved setup in public hall cards and the owner calendar, rather than fixed two-hall lists. */
hallCards=function(){return `<div class="hall-grid">${configuredHalls().map((h,i)=>`<article class="hall-card"><img src="hall.jpg" alt="Illustrative wedding hall ${i+1}"><div class="body"><div class="eyebrow">Venue ${i+1}</div><h2>${esc(h.name)}</h2><p>Up to ${esc(h.capacity)} guests · ${countLabel(h.programs.length,'daily program')}</p><div class="actions">${btn('View hall','route:public/hall'+i,'outline')}${btn('Check availability','public-book:'+i,'gold')}</div></div></article>`).join('')}</div>`};
function scheduleTable(list,dates,link=false){return `<div class="table-wrap"><table><thead><tr><th>Date</th><th>Hall</th><th>Program</th><th>Time</th><th>Availability</th></tr></thead><tbody>${dates.flatMap(d=>list.flatMap((h,i)=>h.programs.map((p,j)=>`<tr><td>${esc(d)}</td><td>${esc(h.name)}</td><td>${esc(p.name)}</td><td>${esc(p.start)}–${esc(p.end)}</td><td>${link?btn('Available','cfg-slot:'+configuredHalls().indexOf(h)+':'+j+':'+d,'outline sm'):badge('Available')}</td></tr>`))).join('')}</tbody></table></div>`}
availability=function(){return `<p class="muted" style="margin-bottom:10px">Daily configured programs · sample availability</p>${scheduleTable(configuredHalls(),['2027-11-20'])}`};
let calDate='2027-11-20',calHall='All halls',calView='Day';
calendar=function(){let list=configuredHalls(),visible=list.filter(h=>calHall==='All halls'||h.name===calHall),dates=Array.from({length:calView==='Week'?7:calView==='Month'?30:1},(_,i)=>{let d=new Date(calDate+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i);return d.toISOString().slice(0,10)});if(!visible.length)visible=list;return pagehead('Hall calendar','Select a hall and date to see its configured daily programs.',btn('New booking','go:newBooking','gold','plus'))+card('Calendar controls',`<div class="fields three">${field('Hall','cfg-calendar-hall','select',calHall,['All halls',...list.map(h=>h.name)])}${field('Date','cfg-calendar-date','date',calDate)}${field('View','cfg-calendar-view','select',calView,['Day','Week','Month'])}</div><div class="actions" style="margin-top:12px">${btn('‹ Previous','cfg-calendar:prev','outline')}${btn('Today','cfg-calendar:today','outline')}${btn('Next ›','cfg-calendar:next','outline')}</div>`)+card('Daily programs',scheduleTable(visible,dates,true))};
const oldPublicPage=publicPage;
publicPage=function(){let i=page.match(/^hall(\d+)$/);if(i){let h=configuredHalls()[+i[1]];if(!h)return publicSection('Our halls','Hall not found','Return to the hall directory.',hallCards());return publicSection('Exclusive venue',esc(h.name),`Capacity: ${esc(h.capacity)} guests · Illustrative photography.`,`<img src="hall.jpg" alt="Illustrative hall" style="width:100%;max-height:420px;object-fit:cover;border-radius:12px"><div class="grid-even" style="margin-top:18px">${card('Daily programs',scheduleTable([h],['2027-11-20']))}${card('Plan your event',`<p>Package from ${money(h.price)}</p><br>${btn('Book this hall','public-book:'+i[1],'gold')}`)}</div>`)}return oldPublicPage()};
const cfgAction=action;
action=function(s){let [a,i,j,date]=s.split(':');if(a==='cfg-calendar'){let d=new Date(calDate+'T12:00:00Z');if(i==='today')d=new Date();else d.setUTCDate(d.getUTCDate()+(i==='next'?1:-1)*(calView==='Week'?7:calView==='Month'?30:1));calDate=d.toISOString().slice(0,10);render();return}if(a==='cfg-slot'){let h=configuredHalls()[+i],p=h?.programs[+j];if(h&&p){booking.hall=h.name;booking.program=p.name;booking.date=date;bookingStep=0;route('venue','newBooking')}return}if(a==='public-book'){let h=configuredHalls()[+i];if(h){booking.hall=h.name;booking.program=h.programs[0].name;bookingStep=0;route('public','booking')}return}cfgAction(s)};
document.addEventListener('change',e=>{let n=e.target.name;if(n==='cfg-calendar-hall')calHall=e.target.value;else if(n==='cfg-calendar-date'&&e.target.value)calDate=e.target.value;else if(n==='cfg-calendar-view')calView=e.target.value;else return;render()},true);
function chosenHall(){let list=configuredHalls();return list.find(h=>h.name===booking.hall)||list[0]}
const eligibleHalls=()=>configuredHalls().filter(h=>+h.capacity>=+booking.guest&&(mode==='public'||typeof hallAllowed!=='function'||hallAllowed(h)));
bookingFlow=function(publicMode){let stages=['Event details','Choose hall & program','Customize quote','Payment','Confirmation'],h=chosenHall(),price=typeof quoteTotals==='function'?quoteTotals(h,publicMode).total:+h.price,percent=Number(installState.config.venue6?.v0??5),deposit=Math.round(price*percent/100),p=h.programs.find(x=>x.name===booking.program)||h.programs[0];let body='';
 if(bookingStep===0)body=`<div class="fields">${field('Event type','event','select',booking.event,['Wedding','Walima','Nikkah','Mehndi','Corporate'])}${field('Event date','date','date',booking.date)}${cfgInput('Expected guests','guest',booking.guest,'number','min="1" step="1"')}${publicMode?`${field('First name','firstName','text',booking.firstName||'')}${field('Last name','lastName','text',booking.lastName||'')}${field('Phone number','phone','tel',booking.phone)}`:`${field('Customer name','name','text',booking.name)}${field('Phone / WhatsApp','phone','tel',booking.phone)}`}</div>`;
 else if(bookingStep===1){let eligible=eligibleHalls();body=`<div class="config-hall-select">${configuredHalls().map((hall,i)=>`<button type="button" data-action="cfg-book-select:${i}" ${+hall.capacity<+booking.guest?'disabled':''} class="config-hall-option ${hall.id===h.id?'selected':''}"><img src="hall.jpg" alt="Illustrative hall"><div class="body"><h3>${esc(hall.name)}</h3><p>Up to ${esc(hall.capacity)} guests · ${money(hall.price)}</p>${badge(+hall.capacity<+booking.guest?'Over capacity':hall.id===h.id?'Selected':'Available')}</div></button>`).join('')}</div>${eligible.length?`<div style="margin-top:16px">${field('Choose a daily program','cfg-book-program','select',p.name,h.programs.map(x=>x.name))}<p class="muted config-help">${esc(p.start)}–${esc(p.end)} · ${esc(p.buffer)} minute cleanup buffer</p></div>`:'<div class="note">No hall can accommodate this guest count. Go back and change your event details.</div>'}`}
 else if(bookingStep===2)body=quoteEditor(h,p,publicMode);
 else if(bookingStep===3)body=paymentBookingFields(deposit,publicMode);
 else body=paymentBookingConfirmation(h,p);
 return `<div class="${publicMode?'bookwrap':''}">${publicMode?'<div class="eyebrow">Plan your celebration</div><h1 style="margin:8px 0 20px">Book your event</h1>':pagehead('New booking','Create a reservation through the guided workflow.')}<div class="steps">${stages.map((s,i)=>`<button class="step ${i===bookingStep?'active':i<bookingStep?'done':''}" data-book-step="${i}"><span class="num">${i<bookingStep?'✓':i+1}</span>${s}</button>`).join('')}</div><div class="booking-card">${card(stages[bookingStep],`<form id="booking-form">${body}${bookingStep<4?`<div class="formfoot"><button type="button" class="btn outline" data-action="book-back" ${bookingStep===0?'disabled':''}>Back</button><button class="btn gold" type="submit">${bookingStep===3?'Confirm synthetic deposit':'Continue →'}</button></div>`:''}</form>`)}${card('Booking summary',`<div class="summary-lines"><div><span>Hall</span><b>${esc(h.name)}</b></div><div><span>Date</span><b>${esc(booking.date)}</b></div><div><span>Program</span><b>${esc(p.name)}</b></div><div><span>Guests</span><b>${esc(booking.guest)}</b></div><div><span>Package total</span><b>${money(price)}</b></div><div class="total"><span>Deposit due</span><b>${money(deposit)}</b></div></div><p class="muted" style="margin-top:15px">Prices and availability are simulated.</p>`,'','calendar')}</div></div>`;
};
const beforeBookingAction=action;
action=function(s){if(s.startsWith('cfg-book-select:')){let h=configuredHalls()[+s.split(':')[1]];if(h&&+h.capacity>=+booking.guest){booking.hall=h.name;booking.program=h.programs[0].name;render()}return}beforeBookingAction(s)};
document.addEventListener('change',e=>{if(e.target.name==='cfg-book-program'){booking.program=e.target.value;render()}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='booking-form')return;e.preventDefault();e.stopImmediatePropagation();let fd=Object.fromEntries(new FormData(e.target));if(typeof checkBookingEmail==='function'&&!checkBookingEmail(fd))return;if(bookingStep===0){Object.assign(booking,fd);let available=eligibleHalls();if(!available.length){toast('No configured hall can accommodate this guest count.');return}if(!available.some(h=>h.name===booking.hall)){booking.hall=available[0].name;booking.program=available[0].programs[0].name}}if(bookingStep===1){let h=chosenHall();if(+h.capacity<+booking.guest){toast('Choose a hall with enough capacity.');return}booking.program=fd['cfg-book-program']||h.programs[0].name;if(!h.programs.some(p=>p.name===booking.program))return}if(bookingStep===2&&!validateQuote(chosenHall(),mode==='public'))return;if(bookingStep===3&&!completeMockPayment(fd,chosenHall(),mode==='public'))return;if(bookingStep<4){bookingStep++;render();window.scrollTo(0,0)}},true);
window.addEventListener('hashchange',()=>{managementDraft=null;synchronizeHallNames()});synchronizeHallNames();render();
